"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["64381"],{22214(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.grupo_formulario.codigo_invalido","status":422,"titulo":"O c\xf3digo do grupo \xe9 obrigat\xf3rio e tem tamanho limitado"},"descricao":{"codigo":"uniplus.grupo_formulario.codigo_invalido","requisitos":["UNI-REQ-0146"],"oQueAconteceu":["O `codigo` do grupo est\xe1 vazio, excede 60 caracteres ou est\xe1 fora do formato. A mensagem \xe9 \\"O c\xf3digo do grupo \xe9 obrigat\xf3rio, come\xe7a com letra mai\xfascula e tem s\xf3 letras mai\xfasculas, algarismos e sublinhados isolados, at\xe9 60 caracteres.\\" O tamanho exato do limite \xe9 da API; o UNI-REQ-0146 define o grupo, n\xe3o o tamanho do c\xf3digo.","A recusa vem na lista `errors` da resposta, com `field` igual a `grupos[i].codigo`, uma entrada por grupo recusado, junto das demais recusas da forma do grupo. Na cria\xe7\xe3o e na atualiza\xe7\xe3o de um modelo de formul\xe1rio o `field` come\xe7a por `conteudo.`. Nada \xe9 gravado.","A recusa vale para o texto presente. A propriedade `codigo` ausente ou nula \xe9 recusada antes, com 400 e sem c\xf3digo deste cat\xe1logo, pela leitura do corpo. Nos modelos, a confer\xeancia da forma do grupo s\xf3 ocorre quando o conte\xfado foi lido sem recusa de leitura (como a de [conte\xfado malformado](/erros/uniplus.configuracao.modelo_formulario.entrada_malformada)), e na atualiza\xe7\xe3o um `{id}` que n\xe3o existe \xe9 recusado antes, como [modelo de formul\xe1rio n\xe3o encontrado](/erros/uniplus.configuracao.modelo_formulario.nao_encontrado)."],"comoResolver":["Informe um `codigo` com texto e de at\xe9 60 caracteres. O c\xf3digo do grupo tamb\xe9m n\xe3o pode coincidir com o c\xf3digo de um fato ou de um grupo de outro formul\xe1rio do processo."],"ondeAparece":["Cria\xe7\xe3o de um modelo de formul\xe1rio","Atualiza\xe7\xe3o de um modelo de formul\xe1rio","Grava\xe7\xe3o dos itens do formul\xe1rio"]},"modulo":{"id":"transversais","nome":"Erros transversais","assunto":"Grupo formulario"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"3eb7bd1a0a2ae187ab8630a6fec1e327066b7a40"}}')}}]);